#!/usr/bin/env node
// tier: T2
/**
 * alpha-token-domain-awareness-inject.mjs — SessionStart hook (slot:alpha ONLY).
 *
 * Surfaces the custom token-optimization DOMAIN awareness surface
 * (`state/shared/TOKEN-OPTIMIZATION-AWARENESS.md`, generated by
 * `scripts/token-awareness-snapshot.mjs`) as `additionalContext` so the alpha chat
 * ALWAYS has its domain context anchored at session start.
 *
 * NOT a duplicate of `token-awareness-inject.mjs` (project hooks): that one injects
 * the live token-ZONE state (GREEN/YELLOW/RED, the 🎚️ block) on every prompt for
 * EVERY slot. This one injects the deep 11-leg PSN synergy headline for ALPHA's own
 * galaxy, once per session. Different content, different cadence, different gating.
 *
 * Gating: emits ONLY for the alpha slot (chat-slots binding OR PRISM_BOOT_SLOT=alpha).
 * Every other slot is a silent no-op. Advisory; never blocks.
 *
 * Knobs:
 *   PRISM_TOKEN_AWARENESS_INJECT_DISABLE=1 → no-op
 *   PRISM_TOKEN_AWARENESS_STALE_HRS=N      → staleness hint threshold (default 24)
 */
import { existsSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const ROOT_CANDIDATES = [
  process.env.PRISM_ROOT,
  "H:/prism-slot-alpha",
  "H:/prism",
];
const AWARENESS_REL = "state/shared/TOKEN-OPTIMIZATION-AWARENESS.md";

function resolveRoot() {
  for (const r of ROOT_CANDIDATES) {
    if (!r) continue;
    try {
      if (existsSync(join(r, "state/shared"))) return r;
    } catch {
      /* fall through */
    }
  }
  return null;
}

function readActiveSlot(root, sessionId) {
  // 1) chat-slots binding (authoritative), 2) PRISM_BOOT_SLOT fallback (durable across resume)
  try {
    const f = join(root, "state/shared/chat-slots.json");
    if (existsSync(f) && sessionId) {
      const data = JSON.parse(readFileSync(f, "utf8"));
      const want = `claude-${String(sessionId).slice(0, 8).toLowerCase()}`;
      const slots = (data && data.slots) || {};
      for (const [slot, state] of Object.entries(slots)) {
        if (state && state.chatId && state.chatId === want) return slot;
      }
    }
  } catch {
    /* fail-soft */
  }
  if (process.env.PRISM_BOOT_SLOT) return String(process.env.PRISM_BOOT_SLOT).toLowerCase();
  return null;
}

// decideRegen -- pure: regenerate the awareness surface before reading?
//   absent -> yes; disabled -> no; age unknown -> no (do not churn); stale -> yes.
// Knob: PRISM_TOKEN_AWARENESS_NO_AUTOREGEN=1 sets disabled (read-only, never regenerate).
export function decideRegen({ fileExists, ageHrs, staleHrs, disabled }) {
  if (disabled) return false;
  if (!fileExists) return true;
  if (ageHrs == null) return false;
  return ageHrs > staleHrs;
}

// maybeRegenerate -- fail-soft: when the surface is stale/absent, regenerate it IN-PROCESS
// by importing the generator's pure exports (no subprocess). R12: a regen failure NEVER
// blocks the inject -- we read whatever is on disk. importImpl is an injectable test seam.
async function maybeRegenerate(root, awarenessFile, staleHrs, io = {}) {
  const importImpl = io.importImpl || ((href) => import(href));
  const disabled = process.env.PRISM_TOKEN_AWARENESS_NO_AUTOREGEN === "1";
  let fileExists = false;
  let ageHrs = null;
  try {
    if (existsSync(awarenessFile)) {
      fileExists = true;
      ageHrs = (Date.now() - statSync(awarenessFile).mtimeMs) / 3_600_000;
    }
  } catch {
    /* fail-soft: treat as unknown */
  }
  if (!decideRegen({ fileExists, ageHrs, staleHrs, disabled })) return false;
  const genPath = join(root, "scripts/token-awareness-snapshot.mjs");
  try {
    if (!existsSync(genPath)) return false;
    const mod = await importImpl(pathToFileURL(genPath).href);
    if (!mod || typeof mod.renderMarkdown !== "function") return false;
    const md = mod.renderMarkdown(
      mod.computeAwareness(mod.gatherInputs()),
      new Date().toISOString(),
    );
    writeFileSync(awarenessFile, md + "\n", "utf8");
    return true;
  } catch {
    return false;
  }
}

function extractHeadline(md, ageHrs, staleHrs) {
  const lines = md.split("\n");
  const verdict = lines.find((l) => l.includes("**Verdict:**")) || "";
  const galaxy = lines.find((l) => l.includes("**Galaxy files:**")) || "";
  const offload = lines.find((l) => /Ollama offload ratio/.test(l)) || "";
  const psn = lines.find((l) => /PSN cumulative savings/.test(l)) || "";
  const attn = lines
    .filter((l) => /^\| \d+\./.test(l) && /[◐○⚠]/.test(l))
    .map((l) => {
      const cells = l.split("|").map((c) => c.trim());
      return `${cells[2] || ""} ${(cells[1] || "").replace(/^\d+\.\s*/, "")}`.trim();
    })
    .slice(0, 6);

  const out = [];
  out.push("## 🪙 Token-optimization domain awareness (slot:alpha custom surface)");
  out.push("");
  if (verdict) out.push(verdict.trim()); // keep balanced **bold** markdown
  if (galaxy) out.push(galaxy.trim());
  if (offload) out.push(offload.replace(/^-\s*/, "").trim());
  if (psn) out.push(psn.replace(/^-\s*/, "").trim());
  if (attn.length) {
    out.push("");
    out.push("**Legs needing attention:** " + attn.join(" · "));
  }
  if (ageHrs != null && ageHrs > staleHrs) {
    out.push("");
    out.push(`⚠ snapshot ${ageHrs.toFixed(0)}h old — regenerate: \`node scripts/token-awareness-snapshot.mjs\``);
  }
  out.push("");
  out.push(
    "_Full: `state/shared/TOKEN-OPTIMIZATION-AWARENESS.md` · galaxy: `mcp-server/src/engines/token-optimization/` · disable: `PRISM_TOKEN_AWARENESS_INJECT_DISABLE=1`._",
  );
  return out.join("\n");
}

async function main() {
  if (process.env.PRISM_TOKEN_AWARENESS_INJECT_DISABLE === "1") process.exit(0);

  let payload = {};
  try {
    const chunks = [];
    for await (const chunk of process.stdin) chunks.push(chunk);
    const s = Buffer.concat(chunks).toString("utf8").trim();
    if (s) payload = JSON.parse(s);
  } catch {
    /* fail-soft */
  }

  const root = resolveRoot();
  if (!root) process.exit(0);

  const slot = readActiveSlot(root, payload.session_id);
  if (!slot || slot.toLowerCase() !== "alpha") process.exit(0); // alpha-only, silent otherwise

  const awarenessFile = join(root, AWARENESS_REL);
  const staleHrs = Number(process.env.PRISM_TOKEN_AWARENESS_STALE_HRS) || 24;
  // U-ALPHA-AWARENESS-AUTOREFRESH: self-heal a stale/absent surface before reading it.
  await maybeRegenerate(root, awarenessFile, staleHrs);
  let block;
  if (!existsSync(awarenessFile)) {
    block =
      "## 🪙 Token-optimization domain awareness (slot:alpha)\n\n" +
      "Snapshot not yet generated. Run: `node scripts/token-awareness-snapshot.mjs`\n\n" +
      "_galaxy: `mcp-server/src/engines/token-optimization/` · disable: `PRISM_TOKEN_AWARENESS_INJECT_DISABLE=1`._";
  } else {
    try {
      const md = readFileSync(awarenessFile, "utf8");
      let ageHrs = null;
      try {
        ageHrs = (Date.now() - statSync(awarenessFile).mtimeMs) / 3_600_000;
      } catch {
        /* ignore */
      }
      block = extractHeadline(md, ageHrs, staleHrs);
    } catch {
      process.exit(0);
    }
  }

  const output = {
    hookSpecificOutput: { hookEventName: "SessionStart", additionalContext: block },
  };
  process.stdout.write(JSON.stringify(output));
}

function invokedAsMain() {
  try {
    return (
      process.argv[1] &&
      resolve(process.argv[1]) === resolve(fileURLToPath(import.meta.url))
    );
  } catch {
    return false;
  }
}

if (invokedAsMain()) main().catch(() => process.exit(0));
